import { describe, expect, test } from "bun:test";

// app/style.css is generated by Tailwind (minified); the hand-written source it is built from is src/styles/*.css.
const stylesDir = new URL("../src/styles/", import.meta.url).pathname;
const files = [...new Bun.Glob("*.css").scanSync(stylesDir)].sort();
const css = (await Promise.all(files.map((f) => Bun.file(stylesDir + f).text()))).join("\n");

/** The bodies of every `@media (prefers-reduced-motion: ...) { ... }` block, brace-matched. */
function reducedMotionBlocks(source: string): string[] {
  const blocks: string[] = [];
  const re = /@media[^{]*prefers-reduced-motion[^{]*\{/g;
  for (let m = re.exec(source); m; m = re.exec(source)) {
    let depth = 1;
    let i = re.lastIndex;
    while (i < source.length && depth > 0) {
      if (source[i] === "{") depth++;
      else if (source[i] === "}") depth--;
      i++;
    }
    blocks.push(source.slice(re.lastIndex, i - 1));
  }
  return blocks;
}

/** Every selector in a block of plain rules (no nested at-rules), comments stripped. */
function selectors(block: string): string[] {
  return block
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .split("}")
    .map((rule) => rule.split("{")[0])
    .flatMap((list) => list.split(","))
    .map((s) => s.trim())
    .filter(Boolean);
}

describe("src/styles reduced motion", () => {
  const blocks = reducedMotionBlocks(css);

  test("the source files are found", () => {
    expect(files).toContain("motion.css");
  });

  test("there is a reduced-motion block (the scan is not vacuous)", () => {
    expect(blocks.length).toBeGreaterThan(0);
    expect(blocks.flatMap(selectors).length).toBeGreaterThan(5);
  });

  test("every prefers-reduced-motion rule is scoped so the dev panel's force-motion toggle can switch it off", () => {
    const unscoped = blocks.flatMap(selectors).filter((s) => !s.startsWith("html:not(.force-motion)"));
    expect(unscoped).toEqual([]);
  });

  test("no nested at-rule hides unscoped selectors", () => {
    for (const b of blocks) expect(b).not.toContain("@");
  });
});

/** The body of the first rule whose selector list contains exactly `selector` (comments stripped). */
function ruleBody(selector: string): string {
  const stripped = css.replace(/\/\*[\s\S]*?\*\//g, "");
  const re = /([^{}]+)\{([^{}]*)\}/g;
  for (let m = re.exec(stripped); m; m = re.exec(stripped)) {
    if (m[1].split(",").some((s) => s.trim() === selector)) return m[2];
  }
  throw new Error(`no rule for ${selector}`);
}

/** The body of `@keyframes name { ... }`, brace-matched. */
function keyframes(name: string): string {
  const start = css.indexOf(`@keyframes ${name}`);
  if (start < 0) throw new Error(`no @keyframes ${name}`);
  const open = css.indexOf("{", start);
  let depth = 1;
  let i = open + 1;
  while (i < css.length && depth > 0) {
    if (css[i] === "{") depth++;
    else if (css[i] === "}") depth--;
    i++;
  }
  return css.slice(open + 1, i - 1);
}

describe("fancy effects: reduced motion and freeze", () => {
  const scoped = reducedMotionBlocks(css)
    .flatMap(selectors)
    .map((s) => s.replace(/^html:not\(\.force-motion\)\s*/, ""));
  const hit = (needle: string) => scoped.some((s) => s.includes(needle));

  test("meteors, the shimmer, the orbit dots and the relocation blur are all switched off by reduced motion", () => {
    expect(hit("#meteors")).toBe(true);
    expect(hit(".shimmer--run")).toBe(true);
    expect(hit(".wx-orbit")).toBe(true);
    expect(hit("#fade.blur-in")).toBe(true);
  });

  test("?freeze=1 hides the meteor layer like the weather canvas", () => {
    expect(css).toMatch(/html\.freeze #meteors/);
  });
});

describe("fancy effects: dimness", () => {
  test("the shimmer highlight peaks at alpha 0.25 at most", () => {
    const alphas = [...ruleBody(".shimmer::after").matchAll(/\/\s*([\d.]+)\s*\)/g)].map((m) => Number(m[1]));
    expect(alphas.length).toBeGreaterThan(0);
    expect(Math.max(...alphas)).toBeLessThanOrEqual(0.25);
  });

  test("an orbiting dot is at most 0.4 opaque", () => {
    const opacity = /opacity:\s*([\d.]+)/.exec(ruleBody(".wx-dot"));
    expect(opacity).not.toBeNull();
    expect(Number(opacity?.[1])).toBeLessThanOrEqual(0.4);
  });

  test("the dots orbit once every 18 to 30 s, at different speeds", () => {
    const periods = [0, 1, 2].map((i) => {
      const m = /animation-duration:\s*([\d.]+)s/.exec(ruleBody(`.wx-orbit--${i}`));
      expect(m).not.toBeNull();
      return Number(m?.[1]);
    });
    for (const p of periods) {
      expect(p).toBeGreaterThanOrEqual(18);
      expect(p).toBeLessThanOrEqual(30);
    }
    expect(new Set(periods).size).toBe(3);
  });

  test("the meteor line takes its alpha and length from the custom properties the code sets", () => {
    const body = ruleBody(".meteor");
    expect(body).toMatch(/var\(--a\)/);
    expect(body).toMatch(/var\(--len\)/);
  });
});

describe("fancy effects: keyframes animate transform and opacity (blur only on the entrance)", () => {
  const props = (name: string) =>
    new Set([...keyframes(name).matchAll(/([a-z-]+)\s*:/g)].map((m) => m[1]).filter((p) => p !== "transform-origin"));

  test("meteor-fly and shimmer-sweep", () => {
    expect([...props("meteor-fly")].sort()).toEqual(["opacity", "transform"]);
    expect([...props("shimmer-sweep")].sort()).toEqual(["opacity", "transform"]);
  });

  test("the orbit is a plain rotation", () => {
    expect([...props("wx-orbit")]).toEqual(["transform"]);
    expect(keyframes("wx-orbit")).toContain("rotate(360deg)");
  });

  test("the theme entrance blur-fades: opacity 0 to 1, blur 8px to 0, 8px up, in 500 ms", () => {
    const body = keyframes("theme-in-blur");
    expect(body).toMatch(/opacity:\s*0/);
    expect(body).toMatch(/opacity:\s*1/);
    expect(body).toContain("blur(8px)");
    expect(body).toMatch(/blur\(0(px)?\)/);
    expect(body).toContain("translateY(8px)");
    expect(body).toMatch(/translateY\(0(px)?\)/);
    expect(ruleBody("#content.is-entering")).toMatch(/theme-in-blur\s+500ms/);
  });

  test("the relocation fade-in blur-fades too, and the leaving animation is unchanged", () => {
    expect(keyframes("blur-in")).toContain("blur(8px)");
    expect(ruleBody("#content.is-leaving")).toMatch(/opacity:\s*0/);
    expect(ruleBody("#content.is-leaving")).toMatch(/scale\(0\.98\)/);
  });

  test("the dev panel's blur-fade switch brings back the old entrance", () => {
    expect(ruleBody("html.no-blur-fade #content.is-entering")).toMatch(/theme-in\s+400ms/);
  });
});
